1,"key_passes":3,"crosses":0,"successful_crosses":0,"takeons":0,"successful_takeons":0},{"player_id":1539,"source_team_id":18,"shots":0,"shots_on_target":0,"key_passes":0,"crosses":0,"successful_crosses":0,"takeons":0,"successful_takeons":0},{"player_id":1542,"source_team_id":10,"shots":0,"shots_on_target":0,"key_passes":0,"crosses":0,"successful_crosses":0,"takeons":1,"successful_takeons":1},{"player_id":1543,"source_team_id":3,"shots":0,"shots_on_target":0,"key_passes":0,"crosses":0,"successful_crosses":0,"takeons":3,"successful_takeons":1},{"player_id":1545,"source_team_id":11,"shots":0,"shots_on_target":0,"key_passes":0,"crosses":5,"successful_crosses":1,"takeons":0,"successful_takeons":0},{"player_id":1573,"source_team_id":15,"shots":2,"shots_on_target":0,"key_passes":0,"crosses":0,"successful_crosses":0,"takeons":1,"successful_takeons":1},{"player_id":1603,"source_team_id":15,"shots":0,"shots_on_target":0,"key_passes":0,"crosses":1,"successful_crosses":1,"takeons":1,"successful_takeons":1}]'::jsonb)
  as x(
    player_id bigint,source_team_id bigint,
    shots integer,shots_on_target integer,key_passes integer,
    crosses integer,successful_crosses integer,
    takeons integer,successful_takeons integer
  )
), eligible as (
  select src.*,p.team_id current_team_id
  from src
  join public.scout_players p on p.id=src.player_id and p.active=true
), team_totals as (
  select e.current_team_id team_id,
         sum(e.shots) filter(where e.source_team_id=e.current_team_id) shots_total,
         sum(e.key_passes) filter(where e.source_team_id=e.current_team_id) chances_total
  from eligible e
  group by e.current_team_id
)
update public.scout_player_season_stats s
set shots=coalesce(s.shots,e.shots),
    shots_on_target=coalesce(s.shots_on_target,e.shots_on_target),
    key_passes=coalesce(s.key_passes,e.key_passes),
    crosses=coalesce(s.crosses,e.crosses),
    successful_crosses=coalesce(s.successful_crosses,e.successful_crosses),
    takeons=coalesce(s.takeons,e.takeons),
    successful_takeons=coalesce(s.successful_takeons,e.successful_takeons),
    shot_share=case
      when e.source_team_id=e.current_team_id and coalesce(tt.shots_total,0)>0
        then e.shots::numeric/tt.shots_total
      else s.shot_share end,
    chance_creation_share=case
      when e.source_team_id=e.current_team_id and coalesce(tt.chances_total,0)>0
        then e.key_passes::numeric/tt.chances_total
      else s.chance_creation_share end,
    advanced_source=case
      when s.advanced_source is not null then s.advanced_source
      when s.shots is not null or s.shots_on_target is not null or s.key_passes is not null
        then 'mixed_reviewed_plus_fresh_sheet_sahadan_gw1_5'
      else 'fresh_sheet_sahadan_gw1_5_2026-09-25'
    end,
    advanced_through_gameweek=greatest(coalesce(s.advanced_through_gameweek,0),5),
    advanced_updated_at=now(),
    updated_at=now()
from eligible e
left join team_totals tt on tt.team_id=e.current_team_id
where s.season='2026-27' and s.player_id=e.player_id;

-- For active players with zero season minutes, zero action totals are observed by definition.
update public.scout_player_season_stats s
set shots=coalesce(s.shots,0),
    shots_on_target=coalesce(s.shots_on_target,0),
    key_passes=coalesce(s.key_passes,0),
    crosses=coalesce(s.crosses,0),
    successful_crosses=coalesce(s.successful_crosses,0),
    takeons=coalesce(s.takeons,0),
    successful_takeons=coalesce(s.successful_takeons,0),
    advanced_source=coalesce(s.advanced_source,'season_zero_minutes'),
    advanced_through_gameweek=greatest(coalesce(s.advanced_through_gameweek,0),coalesce(s.through_gameweek,0)),
    advanced_updated_at=now(),
    updated_at=now()
from public.scout_players p
where p.id=s.player_id and p.active=true
  and s.season='2026-27' and coalesce(s.minutes,0)=0;

commit;
